double avg(double a[], int n)
/* a là mảng gồm n số kiểu double */
{
    int i;
    double sum = 0;
    for (i = 0; i < n; i++) {
        sum += a[i];
    }
    return sum / n;          /* n == 0 ? */
}

int my_strlen(char *string)
/* Khi tính độ dài xâu, hàm này sai ở đâu */
{
    int len = 1;             /* bỏ qua string[0] */
    while (string[len] != '\0')
        len++;
    return len;
}

void class_of_degree(char degree[], double percent)
/* Xếp hạng sinh viên dựa vào tổng điểm tính theo % */
{
    if (percent < 0 || percent > 100)
        strcpy(degree, "Error in mark");
    else if (percent >= 70)
        strcpy(degree, "First");
    else if (percent >= 60)
        strcpy(degree, "Two-one");
    /* .... */
}

#define ASSERT(condition, message) {                 \
    if (!(condition)) {                              \
        fprintf(stderr, "Assertion %s failed: %s\n", \
                #condition, message);                \
        exit(EXIT_FAILURE);                          \
    }                                                \
}

#include <assert.h>
int main() {
    int a;
    printf("Nhap mot gia tri nguyen: \n");
    scanf("%d", &a);
    assert(a >= 10);         /* a < 10: in lỗi ra stderr và abort() */
    printf("Gia tri nguyen vua nhap la %d\n", a);
    return 0;
}

#include <stdlib.h>
#include <stdio.h>

void *safe_malloc(size_t size)
/* Cấp phát bộ nhớ hoặc báo lỗi và thoát */
{
    void *ptr;
    ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr,
            "Không đủ bộ nhớ để thực hiện dòng lệnh :%d file :%s\n",
            __LINE__, __FILE__);
        exit(-1);
    }
    return ptr;
}

#include <iostream>
using namespace std;

double division(int a, int b) {
    if (b == 0) {
        throw "Division by zero!";
    }
    return (a / b);
}

int main() {
    int x = 50;
    int y = 0;
    double z = 0;
    try {
        z = division(x, y);
        cout << z << endl;
    } catch (const char* msg) {
        cerr << msg << endl;
    }
    return 0;
}

